"""Exactly-once crash/effect reconciliation and safe-checkpoint recovery.

Day 9 of Week 4: a process can crash after a modifying tool commits but before
its observation is appended.  On restart the harness must reconcile the effect
receipt, append exactly one observation, and resume from the largest safe
checkpoint — never guessing, never blindly re-running the effect just to
reconstruct model state.

Rules:

- every effect ID reaches one terminal observation;
- an orphaned intent is reconciled, never guessed or blindly rerun;
- replay is deterministic and side-effect-free; effectful tools are never
  re-executed to rebuild context;
- ``largest_safe_checkpoint`` returns the most advanced manifest that still
  passes fail-closed identity/epoch checks, or a cold fallback reason.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from .checkpoint import CacheManifest, ManifestError
from .epoch import ApprovalEpoch, WorldStamp
from .receipts import ReceiptStore

if TYPE_CHECKING:
    from .session import SessionLog


@dataclass(frozen=True)
class ReconciliationResult:
    """Outcome of reconciling one interrupted tool call."""

    tool_call_id: str
    status: str  # "observation_appended" | "no_receipt" | "already_closed"
    receipt_id: str | None = None
    content: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "tool_call_id": self.tool_call_id,
            "status": self.status,
            "receipt_id": self.receipt_id,
            "content": self.content,
        }


def reconcile_effect(
    session: "SessionLog",
    store: ReceiptStore,
    tool_call_id: str,
) -> ReconciliationResult:
    """Close one interrupted effect exactly once.

    If the session already has a ``tool_result`` for the call, it is left
    untouched (exactly-once).  Otherwise the durable receipt is looked up by
    tool-call ID and its verified result is appended as the single terminal
    observation.  A call without a receipt is reported as ``no_receipt`` and
    never re-executed.
    """

    events = session.events
    if any(
        event.type == "tool_result" and event.data.get("tool_call_id") == tool_call_id
        for event in events
    ):
        return ReconciliationResult(tool_call_id, "already_closed")

    receipt = store.by_tool_call(tool_call_id)
    if receipt is None:
        return ReconciliationResult(tool_call_id, "no_receipt")

    session.append(
        "tool_result",
        tool_call_id=tool_call_id,
        tool=receipt.tool,
        arguments=receipt.arguments,
        is_error=receipt.exit_state == "error",
        content=receipt.result,
        reconciled=True,
        receipt_id=receipt.receipt_id,
    )
    return ReconciliationResult(
        tool_call_id,
        "observation_appended",
        receipt_id=receipt.receipt_id,
        content=receipt.result,
    )


def reconcile_interrupted_effects(
    session: "SessionLog",
    store: ReceiptStore,
) -> tuple[ReconciliationResult, ...]:
    """Reconcile every unclosed tool call in one pass, in event order.

    Deterministic and side-effect-free: only the durable receipt store is
    consulted; no tool is re-executed and no receipt is guessed.
    """

    events = session.events
    closed = {
        event.data.get("tool_call_id")
        for event in events
        if event.type == "tool_result" and event.data.get("tool_call_id") is not None
    }
    results = []
    for event in events:
        if event.type != "tool_call":
            continue
        if event.id in closed:
            continue
        results.append(reconcile_effect(session, store, event.id))
        closed.add(event.id)
    return tuple(results)


@dataclass(frozen=True)
class SafeCheckpoint:
    """The largest manifest that may be resumed, or a cold fallback reason."""

    manifest: CacheManifest | None
    reason: str  # "resume" | "cold_no_checkpoint" | "cold_" + reason

    @property
    def can_resume(self) -> bool:
        return self.manifest is not None


def largest_safe_checkpoint(
    manifests: tuple[CacheManifest, ...],
    *,
    world: WorldStamp,
    approval: ApprovalEpoch,
    model_hash: str,
    tokenizer_hash: str,
    layers: int,
) -> SafeCheckpoint:
    """Return the largest checkpoint that passes every fail-closed check.

    ``largest`` means the highest ``position``; ties resolve to the first in
    input order.  Any manifest that mismatches the live model, tokenizer,
    layer geometry, tool catalog, or world/approval epoch is rejected, and if
    none survives the result is cold with the first rejection reason recorded.
    """

    if not manifests:
        return SafeCheckpoint(None, "cold_no_checkpoint")
    valid: list[CacheManifest] = []
    first_reason = "cold_unknown"
    for manifest in manifests:
        try:
            manifest.require_current(
                world=world,
                approval=approval,
                model_hash=model_hash,
                tokenizer_hash=tokenizer_hash,
                layers=layers,
            )
        except ManifestError as error:
            if first_reason == "cold_unknown":
                first_reason = f"cold_{str(error).replace(' ', '_')}"
            continue
        valid.append(manifest)
    if not valid:
        return SafeCheckpoint(None, first_reason)
    best = max(valid, key=lambda manifest: (manifest.position,))
    return SafeCheckpoint(best, "resume")
